+    }
+
+    @Reflect
+    static boolean equality() {
+        return (1 == 1) & (1 != 2);
+    }
+
+    @Reflect
+    static int bitwise() {
+        return (1 & 2) | (3 ^ 4);
+    }
+
+    @Reflect
+    static boolean logical() {
